mkdir -p /tmp/botcheck && cat > /tmp/botcheck/bot.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g5-3/bot.mjs';

const H = 3600_000;
const D = 24 * H;
const t0 = new Date('2026-10-01T10:00:00Z');
const at = (ms) => new Date(t0.getTime() + ms);
let uid = 0;
const fresh = () => `u${++uid}`;

test('never-written customer: both types blocked', () => {
  const u = fresh();
  assert.deepEqual(check(u, 'freeform', at(0)), { allowed: false, rule: 'no-prior-inbound' });
  assert.deepEqual(check(u, 'template', at(0)), { allowed: false, rule: 'no-prior-inbound' });
});

test('freeform: allowed inside 24h of last inbound, blocked at and after 24h', () => {
  const u = fresh();
  onInbound(u, 'my internet is down', at(0));
  assert.deepEqual(check(u, 'freeform', at(D - 1)), { allowed: true, rule: null });
  assert.deepEqual(check(u, 'freeform', at(D)), { allowed: false, rule: 'freeform-window-closed' });
  assert.deepEqual(check(u, 'freeform', at(D + H)), { allowed: false, rule: 'freeform-window-closed' });
});

test('template: allowed after 24h when customer has written before', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  assert.deepEqual(check(u, 'template', at(30 * D)), { allowed: true, rule: null });
});

test('window measured from latest inbound, even when messages arrive out of order', () => {
  const u = fresh();
  onInbound(u, 'later msg', at(2 * D));
  onInbound(u, 'earlier msg delivered late', at(0));
  assert.deepEqual(check(u, 'freeform', at(2 * D + H)), { allowed: true, rule: null });
});

test('STOP variants opt out for both types', () => {
  const variants = [
    'stop', 'STOP', '  Stop  ', 'Stop!', 'stop.', 'S.T.O.P.', 'S T O P',
    'stop 🛑', '🛑 stop', 'ＳＴＯＰ', 'STOPALL', 'stop all', 'Unsubscribe',
    'cancel', 'End', 'quit', '"STOP"', 'stop\n', '​stop​',
  ];
  for (const text of variants) {
    const u = fresh();
    onInbound(u, 'hello', at(0));
    onInbound(u, text, at(1 * H));
    assert.deepEqual(check(u, 'template', at(2 * H)), { allowed: false, rule: 'opted-out' }, JSON.stringify(text));
    assert.deepEqual(check(u, 'freeform', at(2 * H)), { allowed: false, rule: 'opted-out' }, JSON.stringify(text));
  }
});

test('ordinary sentences containing keywords do not opt out', () => {
  const sentences = [
    'please stop calling about the bill', "don't stop", 'my bill has stopped working',
    'can you cancel my appointment', 'the end of the month?', 'stop charging me twice',
    'yes', 'I will quit my job lol', 'quit',
  ];
  for (const text of sentences.slice(0, -1)) {
    const u = fresh();
    onInbound(u, text, at(0));
    assert.deepEqual(check(u, 'freeform', at(H)), { allowed: true, rule: null }, text);
  }
  // Bare "quit" IS a STOP keyword by design.
  const q = fresh();
  onInbound(q, 'quit', at(0));
  assert.equal(check(q, 'freeform', at(H)).rule, 'opted-out');
});

test('after STOP, normal messages do not reopen; START and UNSTOP do', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'STOP', at(H));
  onInbound(u, 'hello?', at(2 * H));
  assert.equal(check(u, 'template', at(3 * H)).rule, 'opted-out');
  onInbound(u, 'start', at(4 * H));
  assert.deepEqual(check(u, 'freeform', at(5 * H)), { allowed: true, rule: null });

  onInbound(u, 'stop', at(6 * H));
  onInbound(u, 'Unstop', at(7 * H));
  assert.deepEqual(check(u, 'template', at(8 * H)), { allowed: true, rule: null });
});

test('bare YES does not re-subscribe; "START please" is not a START keyword', () => {
  const u = fresh();
  onInbound(u, 'STOP', at(0));
  onInbound(u, 'yes', at(H));
  assert.equal(check(u, 'template', at(2 * H)).rule, 'opted-out');
  onInbound(u, 'START please', at(3 * H));
  assert.equal(check(u, 'template', at(4 * H)).rule, 'opted-out');
});

test('opt-out is per customer', () => {
  const a = fresh();
  const b = fresh();
  onInbound(a, 'hi', at(0));
  onInbound(b, 'hi', at(0));
  onInbound(a, 'STOP', at(H));
  assert.equal(check(a, 'template', at(2 * H)).rule, 'opted-out');
  assert.deepEqual(check(b, 'template', at(2 * H)), { allowed: true, rule: null });
});

test('STOP with an invalid timestamp still opts out', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, 'stop', new Date('nope'));
  assert.equal(check(u, 'template', at(H)).rule, 'opted-out');
});

test('unknown type and invalid now fail closed', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  assert.deepEqual(check(u, 'sms', at(H)), { allowed: false, rule: 'unknown-type' });
  assert.deepEqual(check(u, undefined, at(H)), { allowed: false, rule: 'unknown-type' });
  assert.deepEqual(check(u, 'freeform', new Date('nope')), { allowed: false, rule: 'invalid-time' });
});

test('non-string text is not a keyword', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  onInbound(u, null, at(H));
  onInbound(u, undefined, at(H));
  onInbound(u, 42, at(H));
  assert.deepEqual(check(u, 'freeform', at(2 * H)), { allowed: true, rule: null });
});
EOF
cd /tmp/botcheck && node --test bot.test.mjs 2>&1 | tail -40
